#define PYGRAM_UNSUPPORTED_H

#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// CPython 3.11 sys.stdlib_module_names, minus the leading-underscore internals.
static const char pygram_cpython_stdlib[] =
%s;

// Is `name` (a top-level module name, no dots) one CPython ships?
static bool pygram_is_cpython_stdlib(const char *name, size_t len) {
    for (const char *p = pygram_cpython_stdlib; *p; p += strlen(p) + 1) {
        if (strlen(p) == len && memcmp(p, name, len) == 0) {
            return true;
        }
    }
    return false;
}

/*
 * Called from py/builtinimport.c at the two points where a failed import is
 * about to become an ImportError. If the module is one CPython has, this
 * writes the contract line and exits 90; otherwise it returns and the normal
 * ImportError is raised.
 *
 * Exiting here rather than raising a catchable exception is deliberate. The
 * whole point of the 90 is that the CALLER — the shell, the agent loop — sees
 * it; a program that wrapped `import csv` in try/except ImportError would not
 * have taken that branch under CPython either, because under CPython the
 * import succeeds. Suppressing the signal to emulate a branch CPython never
 * takes would be the silent divergence §6 exists to prevent.
 *
 * Writing with write(2) rather than mp_printf keeps this callable from
 * anywhere in the VM, including before the print machinery has anything to
 * say. stdout in the unix port is unbuffered (write(2) per chunk, see
 * ports/unix/unix_mphal.c), so exiting cannot lose output the program already
 * produced — which §7 rule 3 allows a runtime 90 to leave behind.
