static NORETURN void pygram_exit_unsupported_module(const char *name);

static void pygram_check_unsupported_module(const char *name) {
    const char *dot = strchr(name, '.');
    size_t top = dot ? (size_t)(dot - name) : strlen(name);
    if (pygram_is_cpython_stdlib(name, top)) {
        // Report the full dotted name the program asked for ("http.server"),
        // not just the top-level package that failed to resolve.
        pygram_exit_unsupported_module(name);
    }
}

static NORETURN void pygram_exit_unsupported_module(const char *name) {
    char line[128];
    static const char prefix[] = "pygram: unsupported: module: ";
    size_t n = sizeof(prefix) - 1;
    memcpy(line, prefix, n);
    size_t l = strlen(name);
